package au.edu.uow.csci318.assessment.controller;
import au.edu.uow.csci318.assessment.application.AssessmentApplicationService;import au.edu.uow.csci318.assessment.dto.AssessmentDtos.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/assessments") @CrossOrigin public class AssessmentController{private final AssessmentApplicationService service;public AssessmentController(AssessmentApplicationService s){service=s;}
 @PostMapping("/import")@ResponseStatus(HttpStatus.CREATED)public List<Response>importAll(@Valid@RequestBody ImportRequest r){return service.importAll(r);}@PostMapping@ResponseStatus(HttpStatus.CREATED)public Response create(@Valid@RequestBody CreateRequest r){return service.create(r);}@GetMapping public List<Response>all(@RequestParam(required=false)String status,@RequestParam(required=false)UUID subjectId){return service.all(status,subjectId);}@GetMapping("/{id}")public Response one(@PathVariable UUID id){return service.one(id);}@PatchMapping("/{id}")public Response update(@PathVariable UUID id,@RequestBody UpdateRequest r){return service.update(id,r);}@PostMapping("/{id}/complete")public Response complete(@PathVariable UUID id){return service.complete(id);}}
